package br.com.trama.service;
import br.com.trama.dto.*; import br.com.trama.error.*; import br.com.trama.model.*; import br.com.trama.model.enums.StatusCotacao; import br.com.trama.repository.*; import br.com.trama.security.UsuarioPrincipal; import java.time.LocalDateTime; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CotacaoCorporativaService { private final ProdutoRepository produtos; private final CotacaoRepository cotacoes; private final NotificacaoArtesaoRepository notificacoes; private final UsuarioRepository usuarios; public CotacaoCorporativaService(ProdutoRepository p,CotacaoRepository c,NotificacaoArtesaoRepository n,UsuarioRepository u){produtos=p;cotacoes=c;notificacoes=n;usuarios=u;}
 @Transactional public CotacaoResponse criar(CotacaoRequest req,UsuarioPrincipal principal){List<Produto> encontrados=produtos.findByIdIn(req.produtos().stream().distinct().toList());if(encontrados.size()!=req.produtos().stream().distinct().count())throw new BadRequestException("Um ou mais produtos informados não existem.");Usuario empresario=usuarios.findById(principal.getIdUsuario()).orElseThrow(()->new ResourceNotFoundException("Empresário não encontrado."));CotacaoCorporativa c=new CotacaoCorporativa();c.setPrazoEntrega(req.prazoEntrega());c.setStatus(StatusCotacao.EM_ANALISE_ARTESAO);c.setDataCriacao(LocalDateTime.now());c.setEmpresario(empresario);for(Produto p:encontrados){ItemCotacao i=new ItemCotacao();i.setProduto(p);c.adicionarItem(i);}CotacaoCorporativa salva=cotacoes.save(c);Set<Long> ids=new HashSet<>();for(Produto p:encontrados)if(ids.add(p.getArtesao().getId())){NotificacaoArtesao n=new NotificacaoArtesao();n.setArtesao(p.getArtesao());n.setCotacao(salva);n.setMensagem("Nova cotação corporativa recebida. Prazo: "+req.prazoEntrega());n.setDataCriacao(LocalDateTime.now());notificacoes.save(n);}return CotacaoResponse.from(salva);}
}
